     "summary": "10月15日，深圳市住房和建设局、深圳市规划和自然资源局、国家金融监督管理总局深圳监管局联合印发《关于贯彻落实〈关于完善商品住房销售制度的通知〉的实施意见》，自印发之日起施行。根据新规，2026年8月28日起，新公告出让土地的商品住房项目，优先选择现房销售。若申请预售许可，单体建筑须完成主体结构封顶。这意味着今后深圳新拿地项目预售门槛明显提高，购房人买到的房子将更接近完工状态。",
     "source": "经济观察网",
